import React, { Children, cloneElement, forwardRef, isValidElement } from "react";
import { Avatar, AvatarProps } from "@components/avatar";
import { Chip, ChipProps } from "@components/chip";

export const MultiSelectAvatarChip = forwardRef<HTMLSpanElement, ChipProps>(
  ({ children, ...props }: ChipProps, ref: React.ForwardedRef<HTMLSpanElement>) => {
    const childrenWithAvatarSize = Children.map(children, (child) => {
      if (isValidElement<AvatarProps>(child) && child.type === Avatar) {
        return cloneElement(child, { size: "xsm" });
      }

      return child;
    });

    return (
      <Chip hasStartAdornment size="sm" type="outline" variant="neutral" {...props} ref={ref}>
        {childrenWithAvatarSize}
      </Chip>
    );
  },
);
MultiSelectAvatarChip.displayName = "MultiSelect.AvatarChip";
